      let reconstructed = numericKeys.map((key) => raw[key]).join('').trim().replace(/^=/, '');
      try { return JSON.parse(reconstructed); } catch { return { githubRepo: reconstructed }; }
    }
    return raw;
  }
  if (typeof raw === 'string') {
    const cleaned = raw.trim().replace(/^=/, '');
    try { return JSON.parse(cleaned); } catch { return { githubRepo: cleaned }; }
  }
  return {};
}

for (const item of items) {
  const rawIncidentData = item.json.incidentData ?? item.json;
  const data = parseIncidentData(rawIncidentData);

  let deploymentBlocked = false;
  let patchBlocked = false;
  const blockReasons = [];
  if (!data.requestId || !data.incidentId || !data.projectId || !Array.isArray(data.findingIds) || !data.findingIds.length) { patchBlocked=true; blockReasons.push('Missing batch approval correlation'); }
  if (!Array.isArray(data.findings) || data.findings.length !== data.findingIds.length) { patchBlocked=true; blockReasons.push('Finding batch correlation mismatch'); }
  if (data.remediationType !== 'AUTO_FIX_ELIGIBLE') { patchBlocked=true; blockReasons.push('Finding is not auto-fix eligible'); }
  const decision = String(data.decision ?? data.aiAnalysis?.decision ?? '').toUpperCase();
  const riskLevel = String(data.riskLevel ?? data.risk_level ?? data.aiAnalysis?.securityLevel ?? 'low').toLowerCase();
  const confidenceRaw = Number(data.confidenceScore ?? data.confidence_score ?? data.aiAnalysis?.confidenceScore ?? 1);
  const confidenceScore = confidenceRaw > 1 ? confidenceRaw / 100 : confidenceRaw;


  if (decision === 'BLOCK') {
    deploymentBlocked = true;
    blockReasons.push('Judge decision is BLOCK — deployment blocked');
  }

  if (confidenceScore < 0.5) {
    patchBlocked = true;
    deploymentBlocked = true;
    blockReasons.push(`Confidence trop basse: ${confidenceScore}`);
  }

  const githubRepo = String(data.githubRepo ?? data.repository ?? data.repo ?? '').trim().replace(/^=/, '');
  const repoParts = githubRepo.split('/');

  const repositoryOwner = data.repository_owner ?? repoParts[0] ?? '';
  const repositoryName = data.repository_name ?? repoParts[1] ?? '';

  const enrichedData = data.enrichedData ?? data.rawData?.enrichedData ?? {};

  results.push({
    json: {
      ...data,
      deploymentBlocked,
      blocked: patchBlocked,
      block_reason: (patchBlocked || deploymentBlocked) ? blockReasons.join('; ') : 'All constraints passed',
      repository_owner: repositoryOwner,
      repository_name: repositoryName,
      target_file_path: data.files_targeted?.[0] ?? data.target_file_path ?? '',
      default_branch: data.default_branch,
      confidenceScore,
      decision,
      riskLevel,
      enrichedData,
    },
  });
}

